import json
def show(res, qs, n=5, clip=500):
    for q, r in zip(qs, res):
        print("=====", q)
        try:
            items = json.loads(r)
        except Exception as e:
            print("parse err", r[:200]); continue
        for item in items[:n]:
            if item.get("type")!="web_search_result":
                print(item); continue
            print("-", item["title"], "|", item["url"], "|", item.get("page_age"))
            print("   ", item["content"][:clip].replace("\n"," "))
show(res, qs)
